import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('rejects input missing a required property', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'unit_test_tool',
        description: 'A tool for unit testing',
        inputSchema: {
          type: 'object',
          properties: {arg: {type: 'string'}},
          required: ['arg'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('unit_test_tool', {});

    expect({
      calls: executorCalls,
      error: response.result,
    }).toEqual({
      calls: 0,
      error: expect.stringMatching(/missing required property: arg/i),
    });
  });

  it('rejects wrong-typed properties without leaking values', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'secure_tool',
        description: 'A tool that handles secrets',
        inputSchema: {
          type: 'object',
          properties: {secret: {type: 'string'}},
          required: ['secret'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'done';
      }
    );

    const secretValue = 'SECRET_123';
    const response = await registry.execute('secure_tool', {secret: 999});

    expect({
      calls: executorCalls,
      hasField: response.result.includes('secret'),
      hasType: response.result.includes('string'),
      leakedInResult: response.result.includes(String(999)),
      leakedInLogs: recordedLogs.some(line => line.includes(String(999))),
    }).toEqual({
      calls: 0,
      hasField: true,
      hasType: true,
      leakedInResult: false,
      leakedInLogs: false,
    });
  });

  it('passes through valid input with extra properties unchanged', async () => {
    const registry = new ToolRegistry();
    let capturedInput: any;
    registry.register(
      {
        name: 'echo',
        description: 'Echo input',
        inputSchema: {
          type: 'object',
          properties: {foo: {type: 'string'}},
        },
      },
      async input => {
        capturedInput = input;
        return 'ok';
      }
    );

    const input = {foo: 'bar', extra: 'baz'};
    await registry.execute('echo', input);

    expect(capturedInput).toEqual(input);
  });

  it('throws at register time for invalid schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'invalid_schema_tool',
          description: 'Invalid schema',
          inputSchema: {
            type: 'object',
            properties: {val: {type: 'not-a-type' as any}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/invalid_schema_tool/);
  });

  it('caches compiled validators for dynamic tools', async () => {
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {a: {type: 'string'}}};
    let resolvedCount = 0;
    registry.register(
      () => {
        resolvedCount += 1;
        return {
          name: 'dynamic',
          description: 'Dynamic tool',
          inputSchema: schema,
        };
      },
      async () => 'ok'
    );

    await registry.execute('dynamic', {a: 'v1'});
    await registry.execute('dynamic', {a: 'v2'});

    // 1 (register) + 2 (execute) = 3
    expect(resolvedCount).toBe(3);
  });

  it('validates against the current schema for dynamic tools when it changes', async () => {
    const registry = new ToolRegistry();
    let useRequired = false;
    registry.register(
      () => ({
        name: 'changing',
        description: 'Schema changes',
        inputSchema: {
          type: 'object',
          properties: {a: {type: 'string'}},
          required: useRequired ? ['a'] : [],
        },
      }),
      async () => 'ok'
    );

    const r1 = await registry.execute('changing', {});
    const r1Ok = r1.result === 'ok';

    useRequired = true;
    const r2 = await registry.execute('changing', {});
    const r2Failed = r2.result.includes('a') && /required/i.test(r2.result);

    expect({r1Ok, r2Failed}).toEqual({r1Ok: true, r2Failed: true});
  });

  it('still throws Unknown tool for unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('nonexistent', {})).rejects.toThrow(/Unknown tool: nonexistent/);
  });
});

